function withdrawAll() public {
    uint oCredit = credit[address(0)];
    if (oCredit > 0) {
        balance -= oCredit;
        credit[msg.sender] = 0;
        (bool callResult, ) = msg.sender.call{value: oCredit}("");
        require(callResult);
    }
}

