// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint96 amountA, uint96 amountB) public {
        uint256 amtA = uint256(amountA);
        uint256 amtB = uint256(amountB);
        vm.assume(amtA > 0 && amtB > 0);
        vm.assume(amtA < type(uint96).max / 2 && amtB < type(uint96).max / 2);

        address actorA = address(0xA11CE);
        address actorB = address(0xB0B);
        vm.deal(actorA, amtA);
        vm.deal(actorB, amtB);

        uint256 balABefore = actorA.balance;
        uint256 balBBefore = actorB.balance;

        vm.prank(actorA);
        c.deposit{value: amtA}();
        vm.prank(actorB);
        c.deposit{value: amtB}();

        vm.prank(actorA);
        c.withdrawAll();
        vm.prank(actorB);
        c.withdrawAll();

        assertTrue(
            actorA.balance == balABefore && actorB.balance == balBBefore,
            "each account must receive exactly its own deposit back"
        );
    }
}
